static void register_and_run_svc(void)
{
	register SVCXPRT *transp;

	pmap_unset (ISP_RPC, ISP_RPC_VERSION);

	transp = svcudp_create(RPC_ANYSOCK);
	if (transp == NULL) {
		fprintf (stderr, "%s", "cannot create udp service.");
		exit(1);
	}
	if (!svc_register(transp, ISP_RPC, ISP_RPC_VERSION, isp_rpc_1, IPPROTO_UDP)) {
		fprintf (stderr, "%s", "unable to register (ISP_RPC, ISP_RPC_VERSION, udp).");
		exit(1);
	}

	transp = svctcp_create(RPC_ANYSOCK, 0, 0);
	if (transp == NULL) {
		fprintf (stderr, "%s", "cannot create tcp service.");
		exit(1);
	}
	if (!svc_register(transp, ISP_RPC, ISP_RPC_VERSION, isp_rpc_1, IPPROTO_TCP)) {
		fprintf (stderr, "%s", "unable to register (ISP_RPC, ISP_RPC_VERSION, tcp).");
		exit(1);
	}

	svc_run ();
}

