static void *isp_rpc_main(void *arg)
{
	arg = arg;

	prctl(PR_SET_NAME, "ispRpcThread");

	printf("start isp rpc....\n");

	isp_rpc_init_result_mem();

	register_and_run_svc();

	return NULL;
}

static void start_isp_rpc_thread(void)
{
	pthread_t pid;
	pthread_create(&pid, NULL, isp_rpc_main, NULL);
}

void init_isp_rpc(void)
{
	if (access("/tmp/startIspRpc", F_OK) == 0x00) {
		start_isp_rpc_thread();
	}
}

